/* Noto Sans SC 5.3.0 subset for the fixed language-access notice. OFL 1.1. */
@font-face{font-family:'Madison Language Access';font-weight:400;font-style:normal;font-display:block;src:url(data:font/woff;base64,) format('woff')}
.sheet .n-notes{font-family:Arial,'Madison Language Access',sans-serif}


/* R26 action selection and paginated narrative letters */
.r26-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.r26-choice{display:flex;gap:10px;padding:12px;border:1px solid var(--rule);border-radius:8px;align-items:flex-start;margin:6px 0;cursor:pointer}
.r26-choice input{margin-top:4px;flex-shrink:0}.r26-choice small{display:block;margin-top:4px}.r26-reason{font-weight:600}.r26-chooser fieldset{border:0;padding:0;margin:10px 0}.r26-chooser legend{font-weight:700;margin-bottom:8px}
.r26-items{grid-column:1/-1;padding:12px}.r26-items>label{display:block;margin-bottom:8px}#r26-details{margin-bottom:18px}#r26-details textarea{width:100%;font:inherit;box-sizing:border-box}#r26-details details{margin-top:20px}#r26-details summary,.r26-chooser summary{cursor:pointer;font-weight:700;min-height:32px;padding:8px 0}
.sheet table.r26-narrative{border:0;table-layout:fixed}.sheet table.r26-narrative th{padding:0;height:0;border:0;background:none}.sheet table.notice.r26-narrative td{border:0!important;padding:0!important;white-space:pre-line!important;overflow-wrap:anywhere}.sheet table.r26-narrative p{margin:0 0 10pt}.r26-restriction{font-weight:500}
@media(max-width:640px){.r26-groups{grid-template-columns:1fr}.r26-chooser .btn{width:100%}}

@media screen and (min-width:701px){.sheet .r26-header .n-title{font-size:13pt;margin-bottom:3px}.sheet .r26-header{padding-bottom:3px}}

.cit-v9 .amt.cit-mandatory{font-size:11px;white-space:normal;line-height:1.15;font-weight:700;}

.snow-cover{font-size:8.3pt;line-height:1.25}.snow-cover p{margin:0 0 6px}.snow-sites{width:100%;border-collapse:collapse;font-size:8pt;line-height:1.18}.snow-sites th,.snow-sites td{width:50%;padding:3px 6px;vertical-align:top;text-align:left;border:1px solid #999}.snow-sites th{font-weight:700}

/* Adjacent ordinance-review disclosures remain usable touch targets. */
.lib-guidance>summary,.catalog-review>summary,.catalog-review summary{min-height:24px;padding:4px 0;cursor:pointer}

.sheet .snow-cover p{margin-bottom:5px}.sheet .snow-cover .snow-sites th,.sheet .snow-cover .snow-sites td{padding:2px 6px}

/* Measure snow pagination at the same type size used by the locked PDF. */
.sheet .n-body.snow-cover{font-size:9.6pt!important;line-height:1.25}.snow-sheet .n-notes,.snow-sheet .n-foot{font-size:8.4pt!important}.snow-sheet .n-seal{width:80px!important;flex-basis:80px!important}

/* Snow defendant copies retain the comment and all instructions within Letter. */
.cit-v9.cit-snow .cit-cmt{margin-top:6px}.cit-v9.cit-snow .cit-inst{margin-top:8px}.cit-v9.cit-snow .cit-inst-h{margin-bottom:4px}.cit-v9.cit-snow .cit-inst p{margin-bottom:5px}

/* R34 snow cover (authoring 10 only; R33 bodies carry no v10 classes and render unchanged):
   one added body line above the subject, and one blank line between the subject, paragraphs, table and closing line. */
.snow-cover p.snow-subject,.sheet .snow-cover p.snow-subject{padding-top:1.25em;margin:0 0 1.25em}
.snow-cover p.snow-para,.sheet .snow-cover p.snow-para{margin:0 0 1.25em}
/* The table sets 8pt type, so the blank line after it sits on the 8.3pt closing paragraph, where 1.25em is one body line. */
.snow-cover p.snow-closing,.sheet .snow-cover p.snow-closing{margin:1.25em 0 0}
.snow-cover table.snow-sites-v10,.sheet .snow-cover table.snow-sites-v10{margin:0}

/* R47 language discovery and review; fixed print frames are unchanged. */
@media screen{
.language-controls{display:flex;flex-wrap:wrap;align-items:flex-end;gap:12px;margin:18px 0}.language-controls .f{flex:1 1 200px;min-width:0;margin:0}.language-controls .f:first-child{flex:2 1 280px}.language-controls input,.language-controls select{width:100%;min-width:0}
.language-count{font-size:14px;font-weight:600;color:var(--ink)}.language-group{margin:24px 0}.language-group>h2{font-size:15px;color:var(--ink-2);margin-bottom:10px}
.language-row,.language-review-entry{padding:16px 18px;background:var(--surface);border:1px solid var(--rule);border-radius:9px;margin:10px 0;min-width:0}.language-row-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.language-row h3{font-size:16px;margin:0}
.language-ordinance{font-size:12px!important;color:var(--ink-2);margin:5px 0!important;overflow-wrap:anywhere}.language-preview{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink-2);font-size:14px;margin:6px 0}
.language-details>summary{cursor:pointer;font-size:13px;padding:7px 0;min-height:28px;color:var(--ink)}.language-details p{font-size:14px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0}
.language-admin-layout{display:grid;grid-template-columns:minmax(240px,340px) minmax(0,1fr);gap:18px;align-items:start}.language-admin-list{max-height:65vh;overflow:auto}.language-entry{display:grid;gap:6px;width:100%;text-align:left;font:inherit;margin:8px 0;padding:12px;border:1px solid var(--rule);border-radius:7px;background:var(--surface);color:var(--ink);overflow-wrap:anywhere}.language-entry[aria-pressed=true]{border:2px solid var(--civic);background:var(--civic-tint)}.language-entry>span:not(.tag){font-size:12px;color:var(--ink-2)}
.language-review-entry{margin-top:0}.language-review-entry h2{font-size:18px;margin:0 0 8px}.language-review-entry label{display:grid;gap:5px;margin:14px 0;font-size:13px}.language-review-entry input,.language-review-entry select,.language-review-entry textarea{width:100%;min-width:0;box-sizing:border-box;font:inherit;padding:9px;border:1px solid var(--rule);border-radius:5px}.language-review-entry textarea{min-height:110px}.language-review-entry p{font-size:13px;overflow-wrap:anywhere;line-height:1.5}
.picker-box[data-language-context]{color:var(--ink)}.picker-box[data-language-context] .picker-search{display:flex;gap:12px;flex-wrap:wrap}.picker-search .f{flex:1 1 200px;min-width:0;margin:0}.picker-search .f:first-child{flex:2 1 280px}.picker-search .f input,.picker-search .f select{width:100%}.picker-box[data-language-context] .picker-tree,.picker-box[data-language-context] .picker-footer{background:var(--surface)}.picker-box[data-language-context] .picker-footer{flex-wrap:wrap}.picker-box[data-language-context] .tree-g:hover{background:var(--civic-tint);color:var(--ink)}
.language-pick-row{border-bottom:1px solid var(--rule-soft);padding-bottom:5px;margin-bottom:10px;min-width:0}.language-pick-row .gitem{background:var(--surface);color:var(--ink);margin-bottom:0}.language-pick-row .gitem:hover{background:var(--civic-tint)}.language-pick-row .gitem.added{background:var(--ok-tint);border-color:var(--ok)}.language-pick-row .added-label{color:var(--ok)}.language-pick-row .gitem-main{max-width:100%}.language-pick-row .language-details{padding:0 12px}.language-pick-row .chipbar{gap:5px}
@media(max-width:800px){.language-admin-layout{grid-template-columns:minmax(0,1fr)}.language-admin-list{max-height:35vh}.language-controls{display:block}.language-controls .f{margin:12px 0}.language-controls>.btn{width:100%}.picker-box[data-language-context] .picker-search{display:block}.picker-search .f{display:block;margin:8px 0}.picker-footer>[data-language-selected]{font-size:12px}.language-review-entry{padding:14px}.language-entry .tag{white-space:normal}}
}
